import{_ as t,H as a,f as i,i as e}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"06 | 特征工程：数据点石成金，给你的系统赋予灵魂","description":"","frontmatter":{},"headers":[{"level":2,"title":"从特征到特征","slug":"从特征到特征","link":"#从特征到特征","children":[]},{"level":2,"title":"从低维到高维","slug":"从低维到高维","link":"#从低维到高维","children":[]},{"level":2,"title":"从空间到世界","slug":"从空间到世界","link":"#从空间到世界","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI大模型系统实战/06｜特征工程：数据点石成金，给你的系统赋予灵魂.md","filePath":"AI大模型系统实战/06｜特征工程：数据点石成金，给你的系统赋予灵魂.md","lastUpdated":1795452834000}'),n={name:"AI大模型系统实战/06｜特征工程：数据点石成金，给你的系统赋予灵魂.md"};function p(l,s,o,h,E,r){return a(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="_06-特征工程-数据点石成金-给你的系统赋予灵魂" tabindex="-1">06 | 特征工程：数据点石成金，给你的系统赋予灵魂 <a class="header-anchor" href="#_06-特征工程-数据点石成金-给你的系统赋予灵魂" aria-label="Permalink to &quot;06 | 特征工程：数据点石成金，给你的系统赋予灵魂&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>上节课我们学习了 AI 系统的建模策略，你掌握得如何？希望你已经对 AI 系统有了初步的了解。从今天开始，你将学习与 AI 系统特征工程相关的内容。</p><p>特征工程其实是数据工程的一部分，我们把它单独拿出来讲是因为特征工程是数据工程的灵魂，而且它与模型工程也密切相关。从这节课开始，我们的课程也逐渐进入深水区，请你带好泳镜泳帽，我们要开始学游泳了。</p><p>其实特征工程和模型工程没有特别明显的边界，许多特征工程的动作，在足够复杂的模型中已经被自动化掉了，所以你要清楚，特征工程主要是为了帮助模型减轻压力。</p><p>我先用一句话概括一下特征工程的核心工作：特征处理的过程是对数据进行微观和宏观投影的过程，所以虽然叫特征处理，但特征本身其实没有变化，变的只是你观察的维度。接下来，我会循序渐进，带你从不同的维度观察特征。</p><h2 id="从特征到特征" tabindex="-1">从特征到特征 <a class="header-anchor" href="#从特征到特征" aria-label="Permalink to &quot;从特征到特征&quot;">​</a></h2><p>我先举个例子，让你直观理解一下从不同观察角度提取的特征，它们的差异有多大。</p><p>如果将光作为一个特征，你只能告诉模型这里有一条光线。但是如果加上一个三棱镜，你便可以告诉模型，这里有七种颜色的光。</p><p>是不是找到一些感觉了？其实这是在从不同角度刻画你的特征，其实是在寻找特征的特征。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/1.png" alt=""></a></p><p>通常情况下，合理的数据变换能帮助现有模型更好地理解样本中的信息。一个常见的例子是年龄特征，因为往往各年龄段用户的数据量往往参差不齐，所以如果你给模型的特征是年龄，它学起来可能会很吃力。</p><p>这时候做一些离散化处理，比如将年龄转化为老、中、青，这样可以帮助模型快速学到一些宏观的特点。</p><p>同样的道理，如果我们将数值型特征直接给到线性模型，可能会导致模型很难发现特征中的一些非线性特点，这时你可以让它做幂函数、指数函数、三角函数等等这些变化之后再给到线性模型，就可以更好地处理非线性特征了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/2.png" alt=""></a></p><p>当然，除此之外我们还有很多的处理手段，比如对数值特征做归一化，让所有的特征都“一样高”，以免模型觉得取值范围大的特征就更重要。例如模型会以为“年龄”比“气温”先天就更重要。这种谁更重要的事情应该交给模型自己去学习、决定，而在特征中，最重要的是“公平公正”。</p><p>除了单一特征的投影之外，还有多个特征组合使用的方法。这些特征交叉组合的策略在后面的一些复杂模型（如 DeepFM）中已经自动化了。</p><h2 id="从低维到高维" tabindex="-1">从低维到高维 <a class="header-anchor" href="#从低维到高维" aria-label="Permalink to &quot;从低维到高维&quot;">​</a></h2><p>刚才我们学习了如何从微观维度观察一个特征的特征，不过，我们同时有必要从更高的维度来观察你的宏观特征，否则系统会像下图一样，成为一个困在低维的生物，看不到世界的原貌。</p><p>那具体怎么做呢？第一步便是将你的特征映射到更高的维度上，后面的例子会帮助你理解这种映射的必要性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/3.png" alt=""></a></p><p>以性别特征为例，业务平台通常情况下会用枚举值 0、1 和 2 来表示男性、女性和未知。但如果你直接将这些数值传递给模型，会出现什么问题呢？</p><p>模型可能会错误地认为女性 + 女性 = 未知，男性 + 女性 &lt; 未知，未知 &gt; 女性 &gt; 男性。如果把这样的数据给到类似 LR 这类的线性模型，模型可能在学完所有训练数据之后，还是没搞懂男性、女性和未知之间的关系。</p><p>当机器学不会的时候也会“放弃”，它只能将性别的权重学为零，这个特别重要的特征和我们擦肩而过了，是不是特别可惜？</p><p>所以，我们在做特征工程的时候，要提供更加平易近模型的数据，正所谓 “rubbish in rubbishout”。你可能会问，如果它们之间真的有关系呢？</p><p>这是一个非常好的问题，但在没有额外证据之前，你还不能将这些存在线性关系的数值直接传递给模型。你应该先假设男性、女性和未知之间没有线性数值关系，它们是相互独立的。</p><p>还是那句话，即使它们之间存在隐含的关系，也需要交给模型去挖掘和学习。当然如果你能证明它们之间存在关系，稍后我也会教你如何处理。</p><p>现在，你需要设计一种映射方案，将男、女和未知设计成相互独立的值，这样模型才能自己理解这个特征在真实世界中的含义。</p><p>最简单的方法就是保证它们之间在数值上是正交的，确保每个值只占据空间中的一个维度，简而言之就是用各个维度的单位向量表示一个分类，这种编码方式叫独热编码（one-hotencoding）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/4.png" alt=""></a></p><p>因此，独热编码最大的特点就是能够将数据投射到高维空间，并同时保证它们之间的正交关系。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> torch</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输入标签</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">labels </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> torch.tensor([</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 确定OneHot编码的维度</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">num_classes </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 生成OneHot编码</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">onehot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> torch.eye(num_classes)[labels]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(onehot)</span></span></code></pre></div><h2 id="从空间到世界" tabindex="-1">从空间到世界 <a class="header-anchor" href="#从空间到世界" aria-label="Permalink to &quot;从空间到世界&quot;">​</a></h2><p>好了，现在我们的特征已经成功投影到高维空间了，模型也在正交关系中知道了不同性别的独立性，不会再误以为未知 &gt; 女性 &gt; 男性了。</p><p>但是我要回答你刚才的问题了，这三个分类之间真的没有关系吗？</p><p>性别我不知道，但是其他特征，比如兴趣一定有关系，羽毛球与高尔夫、钓鱼之间一定关系更近，而羽毛球与绘画、插花之间一定关系更远。可是在独热编码之后，它们在空间中的距离可是一模一样的，这时候只能让模型不断地总结学习，才可能得到它们之间的关系。</p><p>那么，如果你已经提前知道它们之间的关系了，那有没有抄近道的方法，也能让模型快速理解它们之间的关系呢？其实还真有一个办法，就是把这种真实世界中的关系直接给模型。</p><p>这也涉及到 AI 大模型的关键技术——预训练模型，你可以用它来刻画真实世界中各个实体之间的关系，让模型知道“羽毛球”与“高尔夫”和“插花”之间哪一个“距离”更近。</p><p>那么我们如何获取各个实体在真实世界中的空间关系呢？你可以通过浩如烟海的语料来学习，比如 OpenAI 使用了几乎全网的文章来训练它们的模型，教会模型理解自然语言。当然了，如果你只需要解决“羽毛球与谁关系更近”这种级别的实体关系，找一些常识性的图书和文章，交给模型去学习就好了。</p><p>下面我们说说具体的过程。首先，你需要将上述语料中所有的单词做独热编码，映射到高维空间中，得到单词的高维向量表达。</p><p>不过，这时独热编码所投影出来的全部单词之间，都是正交的关系。所以接下来，我们需要用相邻单词之间的字面距离，来描述它们的空间关系。</p><p>这里使用了对比学习的方法，利用了“你的基友 A 和基友 B 之间更相似的”这类假设，去训练一个模型，来刻画单词之间的相似度。</p><p>那你可能会问，该如何去衡量，语料中词与词的关系呢？这里有两种方法，第一种是跳字模型Skip-gram，第二种是连续词袋模型 CBOW（Continuous Bag of Words）。</p><p>简单来说，跳字模型的目标是，通过给定一个中心词用它来预测前后单词；而在连续词袋模型中，模型的目标是通过前后词来预测中心词。这里有一个假设，那就是在字面上相近位置经常出现的单词之间，相关性会更大。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/5.png" alt=""></a></p><p>举个例子，假设我们的语料中有这么一段话。</p><ul><li>John likes to watch movies and Mary likes to read books.</li></ul><p>那么 CBOW 的训练数据格式如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;John&quot; -&gt; [&quot;likes&quot;]</span></span>
<span class="line"><span>&quot;to&quot; -&gt; [&quot;likes&quot;, &quot;watch&quot;]</span></span>
<span class="line"><span>&quot;likes&quot; -&gt; [&quot;Mary&quot;]</span></span>
<span class="line"><span>&quot;watch&quot; -&gt; [&quot;to&quot;]</span></span>
<span class="line"><span>&quot;movies&quot; -&gt; [&quot;watch&quot;]</span></span>
<span class="line"><span>&quot;and&quot; -&gt; [&quot;movies&quot;]</span></span></code></pre></div><p>Skip-gram 的训练数据格式如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;likes&quot; -&gt; [&quot;John&quot;, &quot;to&quot;]</span></span>
<span class="line"><span>&quot;to&quot; -&gt; [&quot;likes&quot;, &quot;watch&quot;]</span></span>
<span class="line"><span>&quot;watch&quot; -&gt; [&quot;to&quot;, &quot;movies&quot;]</span></span>
<span class="line"><span>&quot;movies&quot; -&gt; [&quot;watch&quot;, &quot;and&quot;]</span></span></code></pre></div><p>随着你的语料不断增加，每个单词后面的链条也会越来越长。这样，模型就能通过统计，知道哪些单词之间的关系更相近了。</p><p>这就是 Word2Vec 的思想，也是 NLP 预训练模型（PTM）的重要工作。现在的 GPT 系列最早也是从 Word2Vec 一步步发展出来的，所以它的重要性不言而喻。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/06/6.png" alt=""></a></p><p>相信你已经理解“特征工程的本质是空间投影的过程”这句话的含义了。</p><p>接下来，你可以思考一下，你所在的业务场景里有哪些数据？如何为这些数据选择合理的空间投影方法，才能对模型更加友好。这节课的目标呢，正是为了让你理解特征工程的定位和价值。不过也请放心，正如我们在开篇时所说，我将在总体回顾的部分给出一个完整的架构方案。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天的内容告一段落，我带你做个回顾总结。这一讲我们解决了特征工程的三大问题。</p><p>首先，你学习了怎样对特征进行微观投影，得到特征的特征。我们用非线性处理、特征组合处理和归一化处理等特征处理方法，让你的特征更好地服务于模型。</p><p>接下来，你还学习了怎样把低维特征投射到高维空间。我们使用独热编码，将特征投射到高维空间，并保证它们在高维空间的独立性，避免对模型造成干扰。</p><p>最后，你学习了怎样在高维空间，刻画特征之间的语义关系，我们用对比学习的方法，刻画了高维空间中的特征距离，也就是单词之间的语义关系，进而让模型“抄近道”理解特征在现实世界中的关系。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>为了更好地巩固今天所学内容，请你尝试回答后面的问题。可以选择一个有把握的，也可以都作答。</p><ol><li><p>独热编码是如何处理分类特征的？</p></li><li><p>为什么需要进行正交的空间投影？</p></li><li><p>解释一下在高维空间刻画特征距离的意义和作用。</p></li></ol><p>恭喜你完成我们第 6 次打卡学习，期待你在留言区和我交流互动。如果你觉得有收获，也欢迎你分享给你身边的朋友，邀 TA 一起讨论。</p>`,65)])])}const c=t(n,[["render",p]]);export{g as __pageData,c as default};
